<template>
  <div class="document-preview-stage" :style="stageStyle">
    <iframe class="document-preview-frame" :srcdoc="previewHtml" :title="title" :style="frameStyle" />
  </div>
</template>

<script setup>
import { computed } from "vue";
import { laboratoryDocumentContext, laboratoryLogoUrl, resolveDocumentTokens } from "@/components/documents/designer/documentPreviewContext.js";
import { resolveRichTextTokens, sanitizeRichTextHtml } from "@/components/documents/designer/richTextContent.js";
import { patientReceiptDocumentAdapter } from "@/components/documents/designer/adapters/patientReceiptDocumentAdapter.js";import{normalizeGenericTable}from"@/components/documents/designer/genericTableModel.js";

const props=defineProps({documentJson:{type:Object,default:null},laboratory:{type:Object,default:null},zoom:{type:Number,default:1},title:{type:String,default:"Vista previa del documento"}});
const pageWidth=computed(()=>Math.max(1,Number(props.documentJson?.page?.width||816)));
const pageHeight=computed(()=>Math.max(1,Number(props.documentJson?.page?.height||1056)));
const stageStyle=computed(()=>({width:(pageWidth.value*props.zoom)+"px",height:(pageHeight.value*props.zoom)+"px"}));
const frameStyle=computed(()=>({width:pageWidth.value+"px",height:pageHeight.value+"px",transform:"scale("+props.zoom+")",transformOrigin:"top left"}));
const escapeHtml=value=>String(value??"").replace(/[&<>"']/g,char=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#39;"})[char]);
const sampleRows=patientReceiptDocumentAdapter.sampleExamRows;
const sampleSummary=patientReceiptDocumentAdapter.sampleSummary;
function resolvePreviewRichText(html,context){
  const documentValue=new DOMParser().parseFromString(String(html||""),"text/html");
  const walker=document.createTreeWalker(documentValue.body,NodeFilter.SHOW_TEXT);
  const nodes=[];while(walker.nextNode())nodes.push(walker.currentNode);
  nodes.forEach(node=>{node.nodeValue=resolveDocumentTokens(node.nodeValue||"",context)});
  return sanitizeRichTextHtml(documentValue.body.innerHTML);
}
function elementHtml(element,offsetX=0,offsetY=0){const x=Number(element.x||0)+offsetX,y=Number(element.y||0)+offsetY,width=Math.max(1,Number(element.width||1)),height=Math.max(1,Number(element.height||1)),base=`position:absolute;left:${x}px;top:${y}px;width:${width}px;height:${height}px;box-sizing:border-box;`;if(element.type==="group")return(element.children||[]).map(child=>elementHtml(child,x,y)).join("");if(element.type==="rich-text"){const context=laboratoryDocumentContext(props.laboratory),content=element.html?resolvePreviewRichText(element.html,context):escapeHtml(resolveDocumentTokens(element.text||"",context));return `<div class="rich-text-content" style="${base}padding:${Number(element.padding||0)}px;font-family:${escapeHtml(element.fontFamily||'Inter')};font-size:${Number(element.fontSize||14)}px;font-weight:${element.bold?700:400};font-style:${element.italic?'italic':'normal'};text-decoration:${element.underline?'underline':'none'};text-align:${element.align||'left'};color:${escapeHtml(element.textColor||'#263238')};background:${escapeHtml(element.backgroundColor||'#ffffff')};line-height:${Number(element.lineHeight||1.2)};--paragraph-gap:${Math.max(0,Number(element.paragraphGap)||0)}px;white-space:pre-wrap;overflow:hidden">${content}</div>`}if(element.type==="separator")return `<div style="${base}height:0;border-top:${Math.max(1,Number(element.borderWidth||1))}px ${element.lineStyle==='dashed'?'dashed':element.lineStyle==='dotted'?'dotted':'solid'} ${escapeHtml(element.strokeColor||'#34495e')};opacity:${Number(element.opacity??100)/100}"></div>`;if(element.type==="rectangle")return `<div style="${base}background:${escapeHtml(element.fillColor||'#eaf1f5')};opacity:${Number(element.opacity??100)/100};border:${Number(element.borderWidth||0)}px ${element.lineStyle==='dashed'?'dashed':element.lineStyle==='dotted'?'dotted':'solid'} ${escapeHtml(element.strokeColor||'#78909c')};border-radius:${Number(element.cornerRadius||0)}px"></div>`;if(element.type==="image"&&element.src)return `<img alt="${escapeHtml(element.alt||'')}" src="${escapeHtml(element.src)}" style="${base}object-fit:${element.fit==='cover'?'cover':element.fit==='stretch'?'fill':'contain'};opacity:${Number(element.opacity??100)/100}" />`;if(element.type==="logo"){const logo=laboratoryLogoUrl(props.laboratory);return logo?`<img alt="Logo del laboratorio" src="${escapeHtml(logo)}" style="${base}object-fit:contain" />`:`<div style="${base}display:grid;place-items:center;color:#526a7a;font-weight:700">Logo no configurado</div>`}if(element.type==="qr")return `<div style="${base}display:grid;place-items:center;border:1px solid #34495e;font-size:28px">QR</div>`;if(element.type==="generic-table"){const table=normalizeGenericTable(element.table),rows=table.rows.map(row=>`<tr style="height:${row.height}px">${row.cells.map((cell,index)=>cell.hidden?"":`<td rowspan="${cell.rowSpan}" colspan="${cell.colSpan}" style="width:${table.columnWidths.slice(index,index+cell.colSpan).reduce((sum,item)=>sum+item,0)}px;background:${escapeHtml(cell.backgroundColor)};color:${escapeHtml(cell.textColor)};font-family:${escapeHtml(cell.fontFamily)};font-size:${cell.fontSize}px;font-weight:${cell.bold?700:400};font-style:${cell.italic?"italic":"normal"};text-decoration:${cell.underline?"underline":"none"};text-align:${cell.align};vertical-align:${cell.verticalAlign};padding:${cell.padding}px;border:${cell.borderWidth}px ${cell.borderStyle} ${escapeHtml(cell.borderColor)}">${escapeHtml(resolveDocumentTokens(cell.content,laboratoryDocumentContext(props.laboratory)))}</td>`).join("")}</tr>`).join("");return `<table style="${base}height:auto;border-collapse:collapse;background:${escapeHtml(table.tableBackground)}">${rows}</table>`}if(element.type==="exam-table"){const columns=element.columns||[],rows=sampleRows,head=element.showHeader===false?'':`<thead><tr>${columns.map(column=>`<th>${escapeHtml(column.title)}</th>`).join('')}</tr></thead>`,body=`<tbody>${rows.map(row=>`<tr>${columns.map(column=>`<td style="text-align:${column.align||'left'}">${escapeHtml(row[column.field]||'')}</td>`).join('')}</tr>`).join('')}</tbody>`,totals=(element.totalRows||[]).filter(row=>row.enabled).map(row=>`<tr class="total-row"><td colspan="${Math.max(1,columns.length-1)}" style="text-align:right;font-weight:${row.bold?'700':'400'}">${escapeHtml(row.label)}</td><td style="text-align:right;font-weight:${row.bold?'700':'400'}">${escapeHtml(sampleSummary[row.field]||'')}</td></tr>`).join('');return `<table style="${base}height:auto;border-collapse:collapse;font-size:11px">${head}${body}<tbody>${totals}</tbody></table>`}return''}
const previewHtml=computed(()=>{const documentJson=props.documentJson;if(!documentJson)return"";const elements=Array.isArray(documentJson.elements)?documentJson.elements:[];return `<!doctype html><html><head><meta charset="utf-8"><style>html,body{margin:0;width:${pageWidth.value}px;height:${pageHeight.value}px;background:#fff;font-family:Inter,Arial,sans-serif;overflow:hidden}.page{position:relative;width:${pageWidth.value}px;height:${pageHeight.value}px;background:#fff;overflow:hidden}table th,table td{border:${elements.some(item=>item.type==='exam-table'&&item.showBorders===false)?0:1}px solid #cfd8dc;padding:6px}table th{background:#eaf1f5}</style></head><body><div class="page">${elements.map(item=>elementHtml(item)).join('')}</div></body></html>`});
defineExpose({pageWidth,pageHeight});
</script>

<style scoped>
.document-preview-stage{position:relative;margin:0 auto}.document-preview-frame{position:absolute;inset:0;display:block;border:0;background:#fff;box-shadow:0 8px 28px rgba(34,59,87,.2)}
.rich-text-content p{margin:0 0 var(--paragraph-gap,0)}
.rich-text-content p:last-child{margin-bottom:0}
</style>
